import test from 'node:test';
import assert from 'node:assert/strict';
import { IDBFactory } from 'fake-indexeddb';
import { PokerRepository, GAME_DATABASE } from './repository.js';
const setup=()=>{const indexedDBImpl=new IDBFactory();return [new PokerRepository('a',{indexedDBImpl}),new PokerRepository('a',{indexedDBImpl}),new PokerRepository('b',{indexedDBImpl}),indexedDBImpl];};
test('same-owner concurrent deals deduct only once',async()=>{const [a,b]=setup();try{await a.read();const all=await Promise.allSettled([a.command({type:'DEAL',operationId:'a'},0),b.command({type:'DEAL',operationId:'b'},0)]);assert.equal(all.filter(r=>r.status==='fulfilled').length,1);const g=await b.read();assert.equal(g.balance,990);assert.equal(g.revision,1);}finally{a.close();b.close();}});
test('refresh restores exact deck and held selection; owner partition is isolated',async()=>{const [a,b,c]=setup();try{let g=await a.read();g=await a.command({type:'DEAL',operationId:'deal'},g.revision);g=await a.command({type:'HOLD',index:2,held:true,operationId:'hold'},g.revision);assert.deepEqual(await b.read(),g);assert.equal((await c.read()).balance,1000);assert.equal((await c.export()).ownerId,'b');assert.equal((await c.export()).round,null);}finally{a.close();b.close();c.close();}});
test('delete tombstone prevents stale tab resurrecting previous round',async()=>{const [a,b]=setup();try{let g=await a.read();g=await a.command({type:'DEAL',operationId:'deal'},g.revision);await a.delete(g.revision);await assert.rejects(()=>b.command({type:'HOLD',index:0,held:true,operationId:'old'},g.revision),/另一个页面/);const n=await b.read();assert.equal(n.round,null);assert.equal(n.balance,1000);assert.ok(n.revision>g.revision);}finally{a.close();b.close();}});
test('closed repo cannot apply delayed operations',async()=>{const [a,b]=setup();await a.read();a.close();await assert.rejects(()=>a.command({type:'DEAL',operationId:'late'},0),/已关闭/);assert.equal((await b.read()).balance,1000);b.close();});
test('corrupt storage fails without silently overwriting user record',async()=>{const [a,b,,idb]=setup();await a.read();const db=await new Promise((resolve,reject)=>{const r=idb.open(GAME_DATABASE,1);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});await new Promise((resolve,reject)=>{const tx=db.transaction('games','readwrite');tx.objectStore('games').put({ownerId:'a',schemaVersion:900,balance:777});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});await assert.rejects(()=>b.read(),/版本/);const raw=await new Promise(resolve=>{const r=db.transaction('games').objectStore('games').get('a');r.onsuccess=()=>resolve(r.result);});assert.equal(raw.balance,777);db.close();a.close();b.close();});

test('prize pool claim is atomic across tabs and other owners cannot collect it',async()=>{const[a,b,c]=setup();try{await a.transaction(g=>({...g,prizePool:{balance:20,lossCount:10,totalContributed:20,totalClaimed:0,cycles:0}}));const outcomes=await Promise.allSettled([a.command({type:'CLAIM_POOL',operationId:'claim-a'},0),b.command({type:'CLAIM_POOL',operationId:'claim-b'},0)]);assert.equal(outcomes.filter(x=>x.status==='fulfilled').length,1);const n=await b.read();assert.equal(n.balance,1020);assert.equal(n.prizePool.balance,0);assert.equal(n.prizePool.lossCount,0);assert.equal((await c.read()).balance,1000);assert.equal((await c.read()).prizePool.balance,0);await assert.rejects(()=>c.command({type:'CLAIM_POOL',operationId:'other'},0));assert.equal((await a.export()).prizePool.totalClaimed,20);}finally{a.close();b.close();c.close();}});
